{
  "title": "AVL 树平衡因子可视化",
  "widget_type": "diagram",
  "loading_messages": ["构建 AVL 树", "计算节点高度与平衡因子"],
  "assistant_text": "点击节点查看其高度 h 与平衡因子 BF，或切换不平衡状态观察 BF 超出范围时的视觉反馈。"
}
<widget_code>
<style>
* { margin:0; padding:0; box-sizing:border-box; }
html, body { width:100%; height:100%; overflow:hidden; }
.root { width:100%; height:100%; min-width:0; min-height:0;
  display:flex; flex-direction:column; background:var(--bg); color:var(--ink);
  font-family:var(--font-sans); }
.stage { flex:1; display:flex; align-items:center; justify-content:center; min-height:0; }
.stage svg { display:block; width:100%; height:100%; max-width:680px; }
.controls { display:flex; align-items:center; gap:12px; padding:8px 16px; flex-shrink:0; }
.controls button { background:var(--bg2); color:var(--ink); border:1px solid var(--line);
  border-radius:8px; padding:6px 16px; font-size:13px; cursor:pointer;
  transition:background .15s, transform .1s; }
.controls button:hover { background:var(--card); }
.controls button:active { transform:scale(.97); }
.readout { display:grid; grid-template-columns:1fr 1fr; gap:8px; padding:8px 16px; flex-shrink:0; }
.readout-item { background:var(--bg2); border-radius:8px; padding:8px 12px; display:flex;
  flex-direction:column; gap:2px; }
.readout-item .label { font-size:11px; letter-spacing:.08em; text-transform:uppercase;
  color:var(--text2); }
.readout-item .value { font-family:var(--font-mono); font-variant-numeric:tabular-nums;
  font-size:16px; font-weight:600; }
.node-text { font-family:var(--font-mono); font-variant-numeric:tabular-nums; }
.h-label { fill:var(--text2); font-size:11px; }
.bf-label { fill:var(--ink); font-size:16px; font-weight:700; }
.node-circle { fill:var(--card); stroke:var(--line); stroke-width:1.5; cursor:pointer;
  transition:stroke .15s, fill .15s; }
.node-circle:hover { stroke:var(--accent); }
.node-circle.selected { stroke:var(--accent); stroke-width:3; }
.node-circle.unbalanced { fill:var(--accent); fill-opacity:.25; }
.edge { stroke:var(--line); stroke-width:1.5; }
</style>
<div class="root">
  <div class="stage">
    <svg viewBox="0 0 680 400" width="100%" height="100%">
      <defs>
        <marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse">
          <path d="M2 1L8 5L2 9" fill="none" stroke="context-stroke" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </marker>
      </defs>
      <g id="edges"></g>
      <g id="nodes"></g>
    </svg>
  </div>
  <div class="controls">
    <button id="toggle-unbalance">切换不平衡</button>
    <button id="reset">重置</button>
  </div>
  <div class="readout">
    <div class="readout-item">
      <span class="label">选中节点</span>
      <span class="value" id="selected-name">根节点</span>
    </div>
    <div class="readout-item">
      <span class="label">全局状态</span>
      <span class="value" id="global-status">平衡</span>
    </div>
  </div>
</div>
<script>
(function() {
  const state = {
    selectedNode: 'root',
    treeStructure: 'balanced'
  };

  const nodeData = {
    balanced: {
      root: { label:'50', h:3, bf:0, cx:340, cy:60, children:['n30','n70'] },
      n30:  { label:'30', h:2, bf:0, cx:180, cy:140, children:['n20','n40'] },
      n70:  { label:'70', h:2, bf:0, cx:500, cy:140, children:['n60','n80'] },
      n20:  { label:'20', h:1, bf:0, cx:100, cy:220, children:[] },
      n40:  { label:'40', h:1, bf:0, cx:260, cy:220, children:[] },
      n60:  { label:'60', h:1, bf:0, cx:420, cy:220, children:[] },
      n80:  { label:'80', h:1, bf:0, cx:580, cy:220, children:[] }
    },
    unbalanced_left: {
      root: { label:'50', h:4, bf:2, cx:340, cy:60, children:['n30','n70'] },
      n30:  { label:'30', h:3, bf:1, cx:180, cy:140, children:['n20','n40'] },
      n70:  { label:'70', h:1, bf:0, cx:500, cy:140, children:[] },
      n20:  { label:'20', h:2, bf:1, cx:100, cy:220, children:['n10'] },
      n40:  { label:'40', h:1, bf:0, cx:260, cy:220, children:[] },
      n10:  { label:'10', h:1, bf:0, cx:60,  cy:300, children:[] }
    },
    unbalanced_right: {
      root: { label:'50', h:4, bf:-2, cx:340, cy:60, children:['n30','n70'] },
      n30:  { label:'30', h:1, bf:0, cx:180, cy:140, children:[] },
      n70:  { label:'70', h:3, bf:-1, cx:500, cy:140, children:['n60','n80'] },
      n60:  { label:'60', h:1, bf:0, cx:420, cy:220, children:[] },
      n80:  { label:'80', h:2, bf:-1, cx:580, cy:220, children:['n90'] },
      n90:  { label:'90', h:1, bf:0, cx:620, cy:300, children:[] }
    }
  };

  const nodeNames = {
    root:'根节点', n30:'左子 30', n70:'右子 70', n20:'左子左 20', n40:'左子右 40',
    n60:'右子左 60', n80:'右子右 80', n10:'10', n90:'90'
  };

  const edgesSvg = document.getElementById('edges');
  const nodesSvg = document.getElementById('nodes');

  function buildTree(treeKey) {
    const data = nodeData[treeKey];
    edgesSvg.innerHTML = '';
    nodesSvg.innerHTML = '';
    for (const [id, nd] of Object.entries(data)) {
      for (const childId of nd.children) {
        const child = data[childId];
        const line = document.createElementNS('http://www.w3.org/2000/svg','line');
        line.setAttribute('x1', nd.cx);
        line.setAttribute('y1', nd.cy + 20);
        line.setAttribute('x2', child.cx);
        line.setAttribute('y2', child.cy - 20);
        line.setAttribute('class','edge');
        edgesSvg.appendChild(line);
      }
    }
    for (const [id, nd] of Object.entries(data)) {
      const g = document.createElementNS('http://www.w3.org/2000/svg','g');
      g.setAttribute('data-id', id);
      g.style.cursor = 'pointer';
      g.addEventListener('click', function() {
        state.selectedNode = id;
        update();
      });
      const circle = document.createElementNS('http://www.w3.org/2000/svg','circle');
      circle.setAttribute('cx', nd.cx);
      circle.setAttribute('cy', nd.cy);
      circle.setAttribute('r', 20);
      circle.setAttribute('class','node-circle');
      if (id === state.selectedNode) circle.classList.add('selected');
      if (nd.bf < -1 || nd.bf > 1) circle.classList.add('unbalanced');
      g.appendChild(circle);
      const hText = document.createElementNS('http://www.w3.org/2000/svg','text');
      hText.setAttribute('x', nd.cx);
      hText.setAttribute('y', nd.cy - 28);
      hText.setAttribute('text-anchor','middle');
      hText.setAttribute('class','h-label node-text');
      hText.textContent = 'h=' + nd.h;
      g.appendChild(hText);
      const bfText = document.createElementNS('http://www.w3.org/2000/svg','text');
      bfText.setAttribute('x', nd.cx);
      bfText.setAttribute('y', nd.cy + 36);
      bfText.setAttribute('text-anchor','middle');
      bfText.setAttribute('class','bf-label node-text');
      bfText.textContent = 'BF=' + (nd.bf >= 0 ? '+' : '') + nd.bf;
      g.appendChild(bfText);
      nodesSvg.appendChild(g);
    }
  }

  function update() {
    const treeKey = state.treeStructure;
    const data = nodeData[treeKey];
    buildTree(treeKey);
    document.getElementById('selected-name').textContent = nodeNames[state.selectedNode] || state.selectedNode;
    const statusMap = { balanced:'平衡', unbalanced_left:'左倾不平衡', unbalanced_right:'右倾不平衡' };
    document.getElementById('global-status').textContent = statusMap[treeKey];
    // verification assertions
    const sel = data[state.selectedNode];
    if (sel) {
      console.assert(sel.h >= 1, 'height >= 1');
      console.assert(sel.bf === sel.h - (sel.children.length ? Math.max(...sel.children.map(c => data[c].h)) : 0) - (sel.children.length < 2 ? 0 : Math.min(...sel.children.map(c => data[c].h))), 'BF formula');
    }
    if (treeKey === 'balanced') {
      for (const nd of Object.values(data)) console.assert(nd.bf >= -1 && nd.bf <= 1, 'balanced BF');
    }
    if (treeKey === 'unbalanced_left') {
      console.assert(data.root.bf === 2, 'root BF=2');
    }
    if (treeKey === 'unbalanced_right') {
      console.assert(data.root.bf === -2, 'root BF=-2');
    }
  }

  document.getElementById('toggle-unbalance').addEventListener('click', function() {
    const order = ['balanced','unbalanced_left','unbalanced_right'];
    const idx = order.indexOf(state.treeStructure);
    state.treeStructure = order[(idx + 1) % order.length];
    if (!nodeData[state.treeStructure][state.selectedNode]) {
      state.selectedNode = 'root';
    }
    update();
  });

  document.getElementById('reset').addEventListener('click', function() {
    state.treeStructure = 'balanced';
    state.selectedNode = 'root';
    update();
  });

  update();
})();
</script>
</widget_code>
